10	import type { CommitData, CommitErrorKind, CommitInfo } from "./commitTypes";
11	import {
12	  E2E_SLOW_SEARCH_DELAY_MS,
13	  getE2eCommitSearchResult,
14	  shouldRejectCommitSearchOnce,
15	} from "./e2eCommitSearchFixtures";
16	import { getCachedCommitSearch, setCachedCommitSearch } from "./commitSearchCache";
17	import { coalesceCommitSearch } from "./commitSearchInFlight";
18	import {
19	  COMMIT_SEARCH_RATE_LIMIT_MAX_SEARCHES,
20	  COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS,
21	  allowCommitSearch,
22	} from "./commitSearchRateLimit";
23	import { githubProfileUrl } from "./githubUrls";
24	import { logger } from "./logger";
25	import { getSearchClientKey } from "./searchClientKey";
