28	const octokit = new Octokit({
29	  auth: process.env.GITHUB_TOKEN,
30	});
31	
32	const GITHUB_SEARCH_TIMEOUT_MS = 10_000;
33	
34	type GitHubErrorDetails = {
35	  message?: string;
36	  rateLimitRemaining?: number;
37	  rateLimitReset?: number;
38	  status?: unknown;
39	};
40	
41	function parseNonNegativeInteger(value: unknown): number | undefined {
42	  if (typeof value === "number") {
43	    return Number.isSafeInteger(value) && value >= 0 ? value : undefined;
44	  }
45	
46	  if (typeof value !== "string" || !/^\d+$/.test(value)) return undefined;
47	
48	  const parsedValue = Number(value);
49	  return Number.isSafeInteger(parsedValue) ? parsedValue : undefined;
50	}
51	
52	function getGitHubErrorDetails(error: unknown): GitHubErrorDetails {
53	  if (typeof error !== "object" || error === null) {
54	    return {};
55	  }
56	
57	  const status = "status" in error ? error.status : undefined;
58	  const message =
59	    "message" in error && typeof error.message === "string" ? error.message : undefined;
60	  const headers =
61	    "response" in error &&
62	    typeof error.response === "object" &&
63	    error.response !== null &&
64	    "headers" in error.response &&
65	    typeof error.response.headers === "object" &&
66	    error.response.headers !== null
67	      ? (error.response.headers as Record<string, unknown>)
68	      : undefined;
69	
70	  return {
71	    message,
72	    rateLimitRemaining: parseNonNegativeInteger(headers?.["x-ratelimit-remaining"]),
73	    rateLimitReset: parseNonNegativeInteger(headers?.["x-ratelimit-reset"]),
74	    status,
75	  };
76	}
77	
78	function isGitHubRateLimitError(errorDetails: GitHubErrorDetails) {
79	  if (errorDetails.status === 429) return true;
80	  if (errorDetails.rateLimitRemaining === 0) return true;
81	
82	  return (
83	    errorDetails.status === 403 && /rate limit|too many requests/i.test(errorDetails.message ?? "")
84	  );
85	}
86	
87	function isTimeoutError(error: unknown, errorDetails: GitHubErrorDetails) {
88	  if (
89	    typeof error === "object" &&
90	    error !== null &&
91	    "name" in error &&
92	    error.name === "AbortError"
93	  ) {
94	    return true;
95	  }
96	
97	  return /aborted|timeout|timed out/i.test(errorDetails.message ?? "");
98	}
99	
100	function isGitHubUnavailableError(errorDetails: GitHubErrorDetails) {
101	  return (
102	    typeof errorDetails.status === "number" &&
103	    errorDetails.status >= 500 &&
104	    errorDetails.status < 600
105	  );
106	}
107	
108	function withTimeoutSignal<T>(callback: (signal: AbortSignal) => Promise<T>) {
109	  const controller = new AbortController();
110	  const timeout = setTimeout(() => controller.abort(), GITHUB_SEARCH_TIMEOUT_MS);
111	
112	  return Promise.resolve()
113	    .then(() => callback(controller.signal))
114	    .finally(() => clearTimeout(timeout));
115	}
116	
117	function parseableDate(value: unknown): string | null {
118	  if (typeof value !== "string" || !value.trim()) return null;
119	  return Number.isNaN(Date.parse(value)) ? null : value;
120	}
121	
122	function mapCommitItem(item: unknown, username: string): CommitInfo | null {
123	  if (typeof item !== "object" || item === null) return null;
124	
125	  const candidate = item as {
126	    commit?: {
127	      message?: unknown;
128	      author?: { date?: unknown } | null;
129	      committer?: { date?: unknown } | null;
130	    };
131	    html_url?: unknown;
132	    sha?: unknown;
133	    repository?: {
134	      name?: unknown;
135	      full_name?: unknown;
136	      owner?: { login?: unknown } | null;
137	    };
138	    author?: {
139	      login?: unknown;
140	      avatar_url?: unknown;
141	      html_url?: unknown;
142	    } | null;
143	  };
144	  const message = candidate.commit?.message;
145	  const htmlUrl = candidate.html_url;
146	  const sha = candidate.sha;
147	  const repositoryName = candidate.repository?.name;
148	  const repositoryFullName = candidate.repository?.full_name;
149	  const repositoryOwner = candidate.repository?.owner?.login;
150	
151	  if (
152	    typeof message !== "string" ||
153	    typeof htmlUrl !== "string" ||
154	    !htmlUrl ||
155	    typeof sha !== "string" ||
156	    !sha ||
157	    typeof repositoryName !== "string" ||
158	    typeof repositoryFullName !== "string" ||
159	    typeof repositoryOwner !== "string"
160	  ) {
161	    return null;
162	  }
163	
164	  const authorDate = candidate.commit?.author?.date;
165	  const committerDate = candidate.commit?.committer?.date;
166	  const date = parseableDate(committerDate) ?? parseableDate(authorDate);
167	  const authorLogin = candidate.author?.login;
168	  const authorAvatarUrl = candidate.author?.avatar_url;
169	  const authorHtmlUrl = candidate.author?.html_url;
170	
171	  if (!date) return null;
172	
173	  return {
174	    message,
175	    date,
176	    html_url: htmlUrl,
177	    sha,
178	    repository: {
179	      name: repositoryName,
180	      owner: repositoryOwner,
181	      full_name: repositoryFullName,
182	    },
183	    author: {
184	      login: typeof authorLogin === "string" ? authorLogin : username,
185	      avatar_url:
186	        typeof authorAvatarUrl === "string" ? authorAvatarUrl : "https://github.com/ghost.png",
187	      html_url: typeof authorHtmlUrl === "string" ? authorHtmlUrl : githubProfileUrl(username),
188	    },
189	  };
190	}
191	
192	export async function getCommits(username: string): Promise<CommitData> {
193	  const runtimeInput: unknown = username;
194	  if (typeof runtimeInput !== "string") {
195	    return commitSearchError("Username is required", "validation");
196	  }
197	
198	  const normalizedUsername = normalizeGitHubUsername(runtimeInput);
199	  if (!normalizedUsername) return commitSearchError("Username is required", "validation");
200	
201	  const validationMessage = getUsernameValidationMessage(normalizedUsername);
202	  if (validationMessage) return commitSearchError(validationMessage, "validation");
203	
204	  if (shouldRejectCommitSearchOnce(normalizedUsername)) {
205	    throw new Error("Synthetic E2E Server Action rejection");
206	  }
207	
208	  const e2eCommitSearchResult = getE2eCommitSearchResult(normalizedUsername);
209	  if (e2eCommitSearchResult) {
210	    if (normalizedUsername === "e2e-slow-result") {
211	      await new Promise((resolve) => setTimeout(resolve, E2E_SLOW_SEARCH_DELAY_MS));
212	    }
213	    return e2eCommitSearchResult;
214	  }
215	
216	  const cacheKey = normalizedUsername.toLowerCase();
217	  const cachedCommitSearch = getCachedCommitSearch(cacheKey);
218	  if (cachedCommitSearch) return cachedCommitSearch;
219	
220	  // Only searches that can still reach GitHub are counted, so an answer the cache already
221	  // holds costs a visitor nothing. A flood of distinct usernames is all misses, which is
222	  // exactly the traffic this bounds. The result is the ordinary rate-limit one: the visitor is
223	  // being asked to slow down either way, and the screen that says so already offers a retry.
224	  const clientKey = await getSearchClientKey();
225	  if (clientKey && !allowCommitSearch(clientKey)) {
226	    logger.warn({
227	      event: "commit_search_rate_limited_client",
228	      fields: {
229	        errorKind: "rate_limit",
230	        limit: COMMIT_SEARCH_RATE_LIMIT_MAX_SEARCHES,
231	        windowMs: COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS,
232	      },
233	    });
234	    // Not shown to anyone: the rate-limit screen's copy comes from the error kind, so this
235	    // stays accurate about which limit was reached rather than blaming GitHub for ours.
236	    return commitSearchError(
237	      "Too many searches at once. Please wait a moment and try again.",
238	      "rate_limit",
239	    );
240	  }
241	
242	  // The cache only helps after a search finishes; concurrent misses for the same username
243	  // would each call GitHub against one shared quota.
244	  return coalesceCommitSearch(cacheKey, () => searchGitHubCommits(normalizedUsername, cacheKey));
245	}
246	
247	async function searchGitHubCommits(
248	  normalizedUsername: string,
249	  cacheKey: string,
250	): Promise<CommitData> {
251	  try {
252	    const response = await withTimeoutSignal((signal) =>
253	      octokit.rest.search.commits({
254	        q: `author:${normalizedUsername}`,
255	        sort: "committer-date",
256	        order: "asc",
257	        per_page: 10,
258	        request: {
259	          signal,
260	        },
261	      }),
262	    );
263	
264	    const items = response.data.items;
265	    // GitHub abandons a commit search that runs too long and still returns 200 with
266	    // whatever it had indexed so far. Treating that as authoritative would claim a
267	    // "first" commit that may not be the earliest one, so it stays flagged and
268	    // uncached; setCachedCommitSearch drops incomplete results.
269	    const isIncompleteSearch = response.data.incomplete_results === true;
270	
271	    if (isIncompleteSearch) {
272	      logger.warn({
273	        event: "github_commit_search_incomplete",
274	        fields: {
275	          itemCount: items?.length ?? 0,
276	        },
277	      });
278	    }
279	
280	    if (!items || items.length === 0) {
281	      const emptyResult = commitSearchError(
282	        isIncompleteSearch ? INCOMPLETE_COMMIT_SEARCH_MESSAGE : EMPTY_COMMIT_SEARCH_MESSAGE,
283	        "empty",
284	        isIncompleteSearch,
285	      );
286	      setCachedCommitSearch(cacheKey, emptyResult);
287	      return emptyResult;
288	    }
289	
290	    const commits = items.flatMap((item, itemIndex) => {
291	      const commit = mapCommitItem(item, normalizedUsername);
292	      if (commit) return [commit];
293	
294	      logger.warn({
295	        event: "github_commit_search_malformed_item",
296	        fields: {
297	          itemIndex,
298	        },
299	      });
300	      return [];
301	    });
302	
303	    // One call establishes the non-empty invariant and builds the result, so the check and the
304	    // construction cannot drift apart the way a separate `length === 0` guard could.
305	    const result = toCommitSearchSuccess(commits, { incomplete: isIncompleteSearch });
306	
307	    if (!result) {
308	      const emptyResult = commitSearchError(
309	        isIncompleteSearch ? INCOMPLETE_COMMIT_SEARCH_MESSAGE : EMPTY_COMMIT_SEARCH_MESSAGE,
310	        "empty",
311	        isIncompleteSearch,
312	      );
313	      setCachedCommitSearch(cacheKey, emptyResult);
314	      return emptyResult;
315	    }
316	
317	    setCachedCommitSearch(cacheKey, result);
318	    return result;
319	  } catch (error: unknown) {
320	    const errorDetails = getGitHubErrorDetails(error);
321	    const { status } = errorDetails;
322	
323	    if (isTimeoutError(error, errorDetails)) {
324	      logger.warn({
325	        event: "github_commit_search_timeout",
326	        fields: {
327	          status: typeof status === "number" ? status : undefined,
328	          errorKind: "timeout",
329	        },
330	      });
331	      return commitSearchError("GitHub took too long to respond. Please try again.", "timeout");
332	    }
333	
334	    if (isGitHubRateLimitError(errorDetails)) {
335	      logger.warn({
336	        event: "github_commit_search_rate_limited",
337	        fields: {
338	          status: typeof status === "number" ? status : undefined,
339	          errorKind: "rate_limit",
340	          rateLimitRemaining: errorDetails.rateLimitRemaining,
341	          rateLimitReset: errorDetails.rateLimitReset,
342	        },
343	      });
344	      return commitSearchError(
345	        "GitHub rate limit reached. Please try again in a few minutes.",
346	        "rate_limit",
347	      );
348	    }
349	
350	    if (isGitHubUnavailableError(errorDetails)) {
351	      logger.error({
352	        event: "github_commit_search_unavailable",
353	        fields: {
354	          status: typeof status === "number" ? status : undefined,
355	          errorKind: "unavailable",
356	        },
357	      });
358	      return commitSearchError(
359	        "GitHub is temporarily unavailable. Please try again soon.",
360	        "unavailable",
361	      );
362	    }
363	
364	    const errorKind: CommitErrorKind = status === 422 ? "validation" : "unknown";
365	    logger.error({
366	      event: "github_commit_search_failed",
367	      fields: {
368	        status: typeof status === "number" ? status : undefined,
369	        errorKind,
370	      },
371	    });
372	
373	    if (status === 422) {
374	      return commitSearchError("Validation failed. User might not exist.", "validation");
375	    }
376	
377	    return commitSearchError("Failed to fetch commits.", "unknown");
378	  }
379	}
