     6	type CacheEntry = {
     7	  expiresAt: number;
     8	  result: CommitData;
     9	};
    10	
    11	const commitSearchCache = new Map<string, CacheEntry>();
    12	
    13	/**
    14	 * Exported so the in-flight map shares one definition with the cache. Both hand a stored or
    15	 * shared result to more than one caller, and neither wants a caller's mutation to reach the
    16	 * other holders of it.
    17	 */
    18	export function copyCommitSearchResult(result: CommitData): CommitData {
    19	  // Copied per variant rather than by spreading the union. `commits.map` returns a plain array,
    20	  // which is no longer assignable to either variant's tuple, and the narrowing is what tells the
    21	  // compiler which shape it is rebuilding -- a success keeps at least one commit, a failure stays
    22	  // empty. Spreading the union and patching `commits` would need a cast to compile, and a cast
    23	  // here is exactly the promise this refactor removes.
    24	  const copyCommit = (commit: CommitInfo): CommitInfo => ({
    25	    ...commit,
    26	    repository: { ...commit.repository },
    27	    author: { ...commit.author },
    28	  });
    29	
    30	  if (!result.found) return { ...result, commits: [] };
    31	
    32	  const [first, ...rest] = result.commits;
    33	
    34	  return { ...result, commits: [copyCommit(first), ...rest.map(copyCommit)] };
    35	}
