    37	function pruneExpiredEntries(now: number) {
    38	  for (const [cacheKey, cached] of commitSearchCache) {
    39	    if (cached.expiresAt <= now) {
    40	      commitSearchCache.delete(cacheKey);
    41	    }
    42	  }
    43	}
    44	
    45	function pruneOldestEntries() {
    46	  while (commitSearchCache.size > COMMIT_SEARCH_CACHE_MAX_ENTRIES) {
    47	    const oldestCacheKey = commitSearchCache.keys().next().value;
    48	    if (oldestCacheKey === undefined) return;
    49	    commitSearchCache.delete(oldestCacheKey);
    50	  }
    51	}
