    54	  const cached = commitSearchCache.get(cacheKey);
    55	
    56	  if (!cached) return null;
    57	
    58	  if (cached.expiresAt <= now) {
    59	    commitSearchCache.delete(cacheKey);
    60	    return null;
    61	  }
    62	
    63	  commitSearchCache.delete(cacheKey);
    64	  commitSearchCache.set(cacheKey, cached);
