     1	import { copyCommitSearchResult } from "./commitSearchCache";
     2	import type { CommitData } from "./commitTypes";
     3	
     4	// The cache only helps once a search has finished. Until then every concurrent request for the
     5	// same username is a separate call to GitHub against one shared token quota -- so a link shared
     6	// with a crowd multiplies into as many upstream searches as there are readers, all asking the
     7	// identical question. Callers that arrive while a search is running now wait for its answer.
     8	//
     9	// Per process, like the cache: a serverless instance coalesces only the requests it serves, and
    10	// the map is empty again on a cold start. It bounds a burst against one instance, not globally.
    11	//
    12	// A joiner inherits the search already in progress, including how much of its 10s timeout budget
    13	// has elapsed -- so joining at 9.5s can surface a timeout almost immediately. That is accepted:
    14	// the key is released either way, so the retry the visitor is offered starts a fresh search with
    15	// a full budget.
    16	const inFlightSearches = new Map<string, Promise<CommitData>>();
    17	
    18	/**
    19	 * Runs `startSearch` for `cacheKey`, or joins the run already in progress for it.
    20	 *
    21	 * The key is released as the search settles, including when it fails: a key left behind would
    22	 * make every later search for that username replay the same failure instead of retrying.
    23	 */
    24	export function coalesceCommitSearch(
    25	  cacheKey: string,
    26	  startSearch: () => Promise<CommitData>,
    27	): Promise<CommitData> {
    28	  const inFlight = inFlightSearches.get(cacheKey);
    29	  // Copies rather than the shared object, so one caller cannot mutate what the others receive.
    30	  if (inFlight) return inFlight.then(copyCommitSearchResult);
    31	
    32	  // Deferred to a microtask so a synchronous throw from startSearch becomes a rejection of the
    33	  // returned promise rather than escaping the call, which would hand the caller an exception
    34	  // where the signature promises a rejection. The key is not stranded either way -- the throw
    35	  // escapes before `set` runs -- and production passes an arrow that does nothing but call an
    36	  // async function, so it cannot throw synchronously. This keeps the helper honest for any
    37	  // other caller.
    38	  //
    39	  // Invoked inside the arrow rather than passed as `.then(startSearch)`, which would call it
    40	  // unbound and hand it the resolution value as an argument.
    41	  const search = Promise.resolve()
    42	    .then(() => startSearch())
    43	    .finally(() => inFlightSearches.delete(cacheKey));
    44	
    45	  inFlightSearches.set(cacheKey, search);
    46	
    47	  return search.then(copyCommitSearchResult);
    48	}
