     1	import { createHash, randomBytes } from "node:crypto";
     2	import { headers } from "next/headers";
     3	
     4	// Identifying a client for rate limiting means holding something about it in memory, in an app
     5	// whose whole promise is that it stores nothing about a search server-side. So it holds the
     6	// least it can: a salted hash of the forwarded address, never the address, never anything
     7	// about what was searched, and never for longer than the limiter's window.
     8	//
     9	// The salt is random per process and never persisted, so the stored keys survive nothing and
    10	// mean nothing outside the instance that made them. It is not a secret from an attacker who
    11	// can already read this process's memory -- a dump would contain both -- but it does stop a
    12	// stored key from being matched against a precomputed digest of an address, and it stops keys
    13	// from being correlated between instances or across a restart.
    14	const CLIENT_KEY_SALT = randomBytes(32);
    15	
    16	// A forwarded header is client-controllable input in the general case. Truncating rather than
    17	// rejecting an implausibly long value matters: rejecting would hand anyone who can set the
    18	// header an unlimited lane by making it absurd. No real client address is anywhere near this.
    19	const MAX_CLIENT_IDENTIFIER_LENGTH = 100;
    20	
    21	/**
    22	 * Reduces a forwarded address to the opaque key the limiter counts, or `null` when the request
    23	 * carries nothing usable.
    24	 */
    25	export function hashClientIdentifier(value: string | null | undefined): string | null {
    26	  if (typeof value !== "string") return null;
    27	
    28	  // A forwarded list is "client, proxy, proxy"; the client is the first hop. Lower-cased so a
    29	  // re-cased IPv6 address is the same client rather than a second allowance.
    30	  const clientIdentifier = value
    31	    .split(",")[0]
    32	    .trim()
    33	    .toLowerCase()
    34	    .slice(0, MAX_CLIENT_IDENTIFIER_LENGTH);
    35	  if (!clientIdentifier) return null;
    36	
    37	  return createHash("sha256").update(CLIENT_KEY_SALT).update(clientIdentifier).digest("hex");
    38	}
    39	
    40	/**
    41	 * The current request's client key, or `null` when there is no request scope or no forwarded
    42	 * address to derive one from.
    43	 *
    44	 * `x-vercel-forwarded-for` is preferred because Vercel sets it itself and, unlike
    45	 * `x-forwarded-for`, it is not the header a proxy in front of Vercel can overwrite. Vercel
    46	 * overwrites `x-forwarded-for` with the connecting address specifically so it cannot be
    47	 * spoofed, so on the deployed app neither header is attacker-controlled; the preference is
    48	 * what keeps that true if the app is ever put behind another proxy.
    49	 *
    50	 * `null` means unlimited, which is the right way for this to fail. There is no request-scoped
    51	 * fallback that identifies a client, and bucketing every unidentified request together would
    52	 * be the global counter this deliberately is not -- one shared allowance that ordinary
    53	 * visitors would exhaust between them. The cache and the in-flight map still apply.
    54	 */
    55	export async function getSearchClientKey(): Promise<string | null> {
    56	  try {
    57	    const requestHeaders = await headers();
    58	
    59	    return (
    60	      hashClientIdentifier(requestHeaders.get("x-vercel-forwarded-for")) ??
    61	      hashClientIdentifier(requestHeaders.get("x-forwarded-for"))
    62	    );
    63	  } catch {
    64	    // `headers()` throws outside a request scope. A search must not fail because of that.
    65	    return null;
    66	  }
    67	}

