    20	export function useCommitSearch() {
    21	  const [result, setResult] = useState<CommitData | null>(null);
    22	  const [lastSearchedUsername, setLastSearchedUsername] = useState("");
    23	  const [recentSearches, setRecentSearches] = useState<string[]>([]);
    24	  const [shareStatus, setShareStatus] = useState("");
    25	  const [isSearching, setIsSearching] = useState(false);
    26	  const [isRetrying, setIsRetrying] = useState(false);
    27	  const [retryError, setRetryError] = useState("");
    28	  const [retryStillPartial, setRetryStillPartial] = useState(false);
    29	  const [, startTransition] = useTransition();
    30	  const nextSearchIdRef = useRef(0);
    31	  const latestSearchIdRef = useRef(0);
    32	  const resultRef = useRef<CommitData | null>(null);
    33	
