    39	    const loadRecentSearches = window.setTimeout(() => {
    40	      setRecentSearches(getStoredRecentSearches());
    41	    }, 0);
    42	
    43	    return () => window.clearTimeout(loadRecentSearches);
    44	  }, []);
    45	
    46	  const runSearch = useCallback((searchUsername: string, options: RunSearchOptions = {}) => {
    47	    // Identity comes from its own counter rather than from the latest-search marker, so
    48	    // it cannot depend on when that marker is assigned. The marker moves separately, and
    49	    // only once the search actually started.
    50	    const searchId = ++nextSearchIdRef.current;
    51	    const isRetry = Boolean(options.isRetry);
    52	
    53	    const started = runCommitSearch(
    54	      searchUsername,
    55	      { updateUrl: options.updateUrl, source: isRetry ? "retry" : undefined },
    56	      {
    57	        isLatestSearch: () => searchId === latestSearchIdRef.current,
    58	        startTransition,
    59	        setLastSearchedUsername,
    60	        setShareStatus,
    61	        applyResult: (data) => {
    62	          setIsSearching(false);
    63	          setIsRetrying(false);
    64	
    65	          // A retry launched from the results view must not destroy the result the
    66	          // visitor is reading: a shared rate limit or timeout would otherwise replace
    67	          // their commits with an error screen for taking the retry the UI offered.
    68	          if (isRetry && !data.found && resultRef.current?.found) {
    69	            setRetryError(getRetryFailureMessage(data));
    70	            return;
    71	          }
    72	
    73	          // "Still" is only true if the previous result was itself partial. A retry from
    74	          // the error panel starts from a failure, so a first partial answer there is
    75	          // news rather than a repeat.
    76	          if (isRetry && data.found && data.incomplete && resultRef.current?.incomplete) {
