    91	    // make the search discard itself.
    92	    latestSearchIdRef.current = searchId;
    93	    setIsSearching(true);
    94	    setIsRetrying(isRetry);
    95	    setRetryError("");
    96	    setRetryStillPartial(false);
    97	  }, []);
