   101	  // moved to, and the busy flag would outlive the search by up to the GitHub timeout.
   102	  const cancelPendingSearch = useCallback(() => {
   103	    latestSearchIdRef.current = ++nextSearchIdRef.current;
   104	    setIsSearching(false);
   105	    setIsRetrying(false);
   106	    setRetryError("");
   107	    setRetryStillPartial(false);
   108	  }, []);
   109	
   110	  const clearRecentSearches = useCallback(() => {
   111	    setRecentSearches([]);
   112	    clearStoredRecentSearches();
   113	  }, []);
