     4	// Recent searches are a best-effort convenience. Reading or writing them can
     5	// fail on corrupt data or a blocked localStorage (private mode, quota, or a
     6	// security policy); none of that should break the page, so we swallow the
     7	// failure and fall back to an empty/no-op result.
     8	
     9	/**
    10	 * Anything may be in storage: hand-edited entries, or values written by another tool using the
    11	 * same key. This app only ever adds a trimmed, validated handle, so junk does not originate here
    12	 * -- though before this sanitizer it could be re-persisted, since a blank that survived the read
    13	 * was written back with the rest of the list on the next successful search. Each entry is
    14	 * trimmed, validated, and deduplicated before it can reach the shortcut buttons.
    15	 *
    16	 * The cap is applied last. Applying it first would let junk consume slots and return fewer
    17	 * shortcuts than the visitor actually has.
    18	 */
    19	function sanitizeStoredSearches(storedSearches: unknown[]) {
    20	  const seen = new Set<string>();
    21	  const searches: string[] = [];
    22	
    23	  for (const storedSearch of storedSearches) {
    24	    if (typeof storedSearch !== "string") continue;
    25	
    26	    const username = normalizeGitHubUsername(storedSearch);
    27	    // `getUsernameValidationMessage` reports no problem with an empty value on purpose: the
    28	    // search form must not show an error before anything has been typed. Storage has no such
    29	    // excuse, so emptiness is rejected here rather than inferred from a missing message --
    30	    // that inference is what let blank entries render as bare `@` shortcuts.
    31	    if (!username || getUsernameValidationMessage(username)) continue;
    32	
    33	    const duplicateKey = username.toLowerCase();
    34	    if (seen.has(duplicateKey)) continue;
    35	
    36	    seen.add(duplicateKey);
    37	    searches.push(username);
    38	    if (searches.length === MAX_RECENT_SEARCHES) break;
    39	  }
    40	
    41	  return searches;
    42	}
