2	// Guards the three repository-level claims that nothing else can check, and that are wrong quietly
3	// rather than loudly when they break:
4	//
5	//   1. AGENTS.md is the single source of agent instructions. CLAUDE.md and GEMINI.md must stay
6	//      byte-for-byte pointers to it. Claude Code's `#` shortcut appends learnings to CLAUDE.md,
7	//      which is exactly the drift this guards against: the check fails, and the content moves to
8	//      AGENTS.md instead. .github/copilot-instructions.md must not exist, since it would outrank it.
9	//   2. The tooling-state directories are ignored by every gate that reads source, which is what
10	//      makes the unread-path verification exemption in AGENTS.md sound. Prettier and ESLint ignore
11	//      them by name; Vitest reaches the same result by collecting only from the product-code roots,
12	//      so that check reads its scope rather than a list of exclusions.
13	//   3. `npm run validate` is the one definition of the validation gate: CI invokes that script, and
14	//      the two places that write the chain out in order still match it.
15	//
16	// Inputs are therefore wider than the name suggests: AGENTS.md and the pointer files, .prettierignore,
17	// eslint.config.mjs, vitest.config.mts, package.json, .github/workflows/ci.yml, docs/development.md,
18	// and .claude/agents/verifier.md. Step 7 of AGENTS.md maps each of those to this command.
19	//
20	// Usage:
21	//   node scripts/check-agent-docs.mjs          verify (exit 1 on drift)
22	//   node scripts/check-agent-docs.mjs --fix    rewrite the pointer files from the template
23	
24	import { readdir, readFile, writeFile } from "node:fs/promises";
25	import { dirname, join } from "node:path";
26	import { fileURLToPath } from "node:url";
27	
28	import { chainedCommands, gateBlock, workflowRunsScript } from "./gate-commands.mjs";
29	import { globRoots, hasGitignoreEntry, hasQuotedEntry } from "./ignore-entries.mjs";
30	import { installedBrowsers, requiredEngines, runsBrowserSuite } from "./browser-projects.mjs";
31	
32	const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
33	const CANONICAL_DOC = "AGENTS.md";
34	const MIN_CANONICAL_LINES = 20;
35	const WRAP_COLUMNS = 100;
36	
37	// `link` is the path to AGENTS.md relative to the pointer file's own directory. Both current
38	// pointers sit at the repo root, so both use "AGENTS.md"; a pointer added under a subdirectory
39	// needs its own relative path, for example "../AGENTS.md".
40	const POINTER_DOCS = [
41	  {
42	    file: "CLAUDE.md",
43	    title: "Claude Code",
44	    link: "AGENTS.md",
45	    note: "Anything captured with the `#` shortcut during a session belongs in",
46	  },
47	  {
48	    file: "GEMINI.md",
49	    title: "Gemini CLI",
50	    link: "AGENTS.md",
51	    note: "Anything worth remembering belongs in",
52	  },
53	];
54	
55	// Files that must not exist. GitHub ranks .github/copilot-instructions.md above AGENTS.md, so a
56	// regenerated one would quietly become the highest-precedence instruction source and AGENTS.md
