93	function wrap(text, width) {
94	  const lines = [];
95	  let current = "";
96	
97	  for (const word of text.split(" ")) {
98	    if (current === "") {
99	      current = word;
100	    } else if (`${current} ${word}`.length <= width) {
101	      current = `${current} ${word}`;
102	    } else {
103	      lines.push(current);
104	      current = word;
105	    }
106	  }
107	
108	  if (current !== "") lines.push(current);
109	  return lines.join("\n");
110	}
