112	function expectedContent({ title, link, note }) {
113	  const paragraphs = [
114	    `# ${title}`,
115	    `Project instructions for this repository live in one canonical file: [${CANONICAL_DOC}](${link}).`,
116	    `Read [${CANONICAL_DOC}](${link}) for commands, layout, gotchas, and conventions.`,
117	    `Do not add project instructions to this file. ${note} [${CANONICAL_DOC}](${link}) instead. ` +
118	      "CI runs `npm run check:agent-docs`, which fails if this file drifts from the pointer template.",
119	  ];
120	
121	  return `${paragraphs.map((paragraph) => wrap(paragraph, WRAP_COLUMNS)).join("\n\n")}\n`;
122	}
