133	function firstDifference(actual, expected) {
134	  const actualLines = actual.split("\n");
135	  const expectedLines = expected.split("\n");
136	
137	  for (let index = 0; index < Math.max(actualLines.length, expectedLines.length); index += 1) {
138	    if (actualLines[index] !== expectedLines[index]) {
139	      return {
140	        line: index + 1,
141	        actual: actualLines[index] ?? "<end of file>",
142	        expected: expectedLines[index] ?? "<end of file>",
143	      };
144	    }
145	  }
146	
147	  return null;
148	}
